function milestonesFor(childId){
  return S.milestones.filter(m=>m.child_id===childId)
}
function milestoneStats(childId){
  let arr=milestonesFor(childId);
  return {achieved:arr.filter(m=>m.achieved).length,total:arr.length}
}
function milestonesView(){
  return`<section class="section ${tab==='child'&&childSection==='milestones'?'active':''}"><div class="stack">
  <button class="btn secondary small" data-back-child="1">‹ Menu Anak</button>
  <div class="card hero"><div class="content"><p>Rekam jejak tumbuh kembang</p><h2>Milestone Belajar Anak</h2><div class="progress-box"><p>Tandai pencapaian anak per fase. Referensi fase memakai acuan Capaian Pembelajaran Kurikulum Merdeka (Fondasi, A-F), tapi Anda bebas mengikutinya longgar atau ketat sesuai metode homeschooling keluarga.</p></div></div></div>
  ${!S.children.length?`<div class="card"><div class="content"><div class="empty">Tambah data anak dulu di menu Anak sebelum mencatat milestone.</div></div></div>`:S.children.map(c=>{
    let ms=milestonesFor(c.id),stat=milestoneStats(c.id);
    return`<div class="card"><div class="content"><div class="title-row"><div><h3>${esc(c.name)}</h3><p class="muted">${stat.achieved}/${stat.total} milestone tercapai</p></div><div class="inline-actions">${!ms.length?`<button class="btn secondary small" data-open="seedmethod:${c.id}">Template</button>`:''}<button class="btn small" data-open="milestone:${c.id}">${icon('plus')}</button></div></div><div class="grid two" style="margin-top:12px">${
      ms.length?ms.map(m=>`<div class="item"><div class="row"><div class="grow"><span class="pill">${esc(m.fase||'A')}</span><h4 style="margin:10px 0 4px">${esc(m.title)}</h4><p class="muted">${esc(m.description||'')}</p>${m.achieved?`<p class="muted">Tercapai: ${esc((m.achieved_at||'').slice(0,10))}</p>`:''}</div><button class="trash" data-del-milestone="${m.id}">${icon('trash')}</button></div><button class="btn small full ${m.achieved?'secondary':''}" style="margin-top:12px" data-toggle-milestone="${m.id}" data-achieved="${m.achieved?'1':'0'}">${m.achieved?icon('check')+' Tercapai':'Tandai Tercapai'}</button></div>`).join(''):`<div class="empty">Belum ada milestone. Klik Template untuk mulai, atau tambah manual.</div>`
    }</div></div></div>`
  }).join('')}
  </div></section>`}
