function memberName(uid){
  let m=S.members.find(x=>x.user_id===uid);
  return m?(m.profiles?.full_name||m.profiles?.email||uid.slice(0,8)):(uid?uid.slice(0,8):'-')
}
function choreLeaderboard(){
  let totals={};
  S.choreLogs.forEach(l=>{totals[l.done_by]=(totals[l.done_by]||0)+(l.points||0)});
  return Object.entries(totals).map(([uid,points])=>({uid,points,name:memberName(uid)})).sort((a,b)=>b.points-a.points)
}
